  // The whole generator: goal + diet + a calorie target in → a full day of
  // meals out. Nothing here touches the database — pure function, recomputed
  // live any time an input changes.
  function generateMealPlan(goalKey, dietKey, calories) {
    const goal = MEAL_GEN_GOALS[goalKey];
    const diet = MEAL_GEN_DIETS[dietKey];
    const target = [
      (calories * goal.split[0]) / 4,
      (calories * goal.split[1]) / 4,
      (calories * goal.split[2]) / 9
    ];
    const vf = mealGenVector(diet.fixed);
    const vP = mealGenVector(diet.P);
    const vC = mealGenVector(diet.C);
    const vF = mealGenVector(diet.F);
    const need = [target[0] - vf[0], target[1] - vf[1], target[2] - vf[2]];
    // Floor of 0.35 keeps hard combinations (e.g. aggressive vegan fat loss)
    // from producing negative or near-zero portions.
    const k = mealGenSolve3([vP, vC, vF], need).map((x) => Math.max(x, 0.35));

    const items = [
      ...diet.fixed.map((it) => ({ ...it, grams: it.grams })),
      ...diet.P.map((it) => ({ ...it, grams: it.grams * k[0] })),
      ...diet.C.map((it) => ({ ...it, grams: it.grams * k[1] })),
      ...diet.F.map((it) => ({ ...it, grams: it.grams * k[2] }))
    ].map((it) => ({ ...it, grams: Math.max(5, Math.round(it.grams / 5) * 5) }));

    let achP = 0, achC = 0, achF = 0;
    items.forEach((it) => {
      const d = MEAL_GEN_FOODS[it.food];
      achP += (d.p * it.grams) / 100;
      achC += (d.c * it.grams) / 100;
      achF += (d.f * it.grams) / 100;
    });
    const achievedCalories = Math.round(achP * 4 + achC * 4 + achF * 9);

    const meals = { B: [], L: [], S: [], D: [] };
    items.forEach((it) => {
      const perMeal = it.grams / it.meals.length;
      it.meals.forEach((m) => meals[m].push({ food: it.food, grams: perMeal }));
    });

    const offBy = achievedCalories - calories;
    return {
      targetCalories: calories,
      achievedCalories,
      achievedProtein: Math.round(achP),
      achievedCarbs: Math.round(achC),
      achievedFat: Math.round(achF),
      meals,
      offBy,
      showClosestMatchNote: Math.abs(offBy) / calories > 0.07
    };
  }

