  // come from the food-lookup edge function, which checks your own curated
  // Lebanese-dish list first, then falls back to the free USDA database.
  // Phone camera photos can easily be several MB at full resolution — shrink
  // to a reasonable size before it ever leaves the device, both so the
  // upload is fast on a weak connection and so it stays comfortably under
  // any request-size limit. Falls back to the original file if anything
  // about image decoding fails (older browsers, unusual formats).
  function resizeImageFile(file, maxDim = 1024, quality = 0.82) {
    return new Promise((resolve) => {
      try {
        const img = new Image();
        const url = URL.createObjectURL(file);
        img.onload = () => {
          let { width, height } = img;
          if (width > maxDim || height > maxDim) {
            const scale = maxDim / Math.max(width, height);
            width = Math.round(width * scale);
            height = Math.round(height * scale);
          }
          const canvas = document.createElement("canvas");
          canvas.width = width; canvas.height = height;
          const ctx = canvas.getContext("2d");
          ctx.drawImage(img, 0, 0, width, height);
          URL.revokeObjectURL(url);
          canvas.toBlob((blob) => resolve(blob || file), "image/jpeg", quality);
        };
        img.onerror = () => resolve(file);
        img.src = url;
      } catch (e) { resolve(file); }
    });
  }

