  // Client-facing "build me a plan right now" flow — 3 quick picks (goal,
  // diet, calories) then a live-computed day of meals. Nothing here is saved;
  // changing any answer just recomputes instantly. Sits alongside (not
  // instead of) the ready-templates browser and the custom-plan request.
  // saved (when present, as {goal, diet, calories}) means the client already
  // confirmed a plan — render that result read-only, no picker, so reopening
  // the app always shows the same plan instead of asking them to choose
  // again. With no saved plan yet, canConfirm=true (the normal client path)
  // shows the picker plus a "Confirm & save" step; canConfirm=false is the
  // old free-preview behavior, unused by DietPanel now but kept in case a
  // manager wants a no-commitment preview later.
  function InstantMealPlanPanel({ onClose, clientName, saved = null, onSaved, canConfirm = true }) {
    const [genGoal, setGenGoal] = useState((saved && saved.goal) || MEAL_GEN_GOAL_OPTIONS[0].value);
    const [genDiet, setGenDiet] = useState((saved && saved.diet) || MEAL_GEN_DIET_OPTIONS[0].value);
    const [genCalories, setGenCalories] = useState((saved && saved.calories) || null);
    const [showSwaps, setShowSwaps] = useState(false);
    const [saving, setSaving] = useState(false);
    const [saveError, setSaveError] = useState("");

    const locked = !!saved;
    const dietKey = genDiet === "lactose_free" ? "lactose_free" : genDiet;
    const bands = MEAL_GEN_GOALS[genGoal].bands;
    const bandLabels = ["Lower", "Middle", "Higher"];
    const result = useMemo(
      () => (genCalories != null ? generateMealPlan(genGoal, dietKey, genCalories) : null),
      [genGoal, dietKey, genCalories]
    );
    const swaps = MEAL_GEN_SWAPS[dietKey] || MEAL_GEN_SWAPS.standard;

    // Only ever writes the caller's own diet_plans row (same SECURITY
    // DEFINER pattern as request_diet_plan) — a client has no direct write
    // access to diet_plans otherwise.
    async function handleConfirm() {
      if (!sb || !result) return;
      setSaveError("");
      setSaving(true);
      const { error: err } = await sb.rpc("save_instant_meal_plan", {
        p_client_name: clientName, p_goal: genGoal, p_diet: genDiet, p_calories: genCalories
      });
      setSaving(false);
      if (err) { setSaveError("Couldn't save: " + err.message); return; }
      if (onSaved) onSaved({ goal: genGoal, diet: genDiet, calories: genCalories });
    }

    return e("div", { style: { ...styles.sessionForm, marginTop: 10 } },
      e("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center" } },
        e("span", { style: { fontFamily: "'Oswald', sans-serif", fontWeight: 600, fontSize: 13, letterSpacing: "0.02em", color: C.ink } }, "Instant meal plan"),
        !locked && onClose && e("button", { style: { ...styles.demoLinkBtn, padding: "0 10px" }, onClick: onClose }, "Close")
      ),
      locked
        ? e("p", { style: { ...styles.profileGoalText, fontSize: 12, marginTop: 4 } }, "This is your confirmed plan — ask your gym if you'd like a different one.")
        : e("p", { style: { ...styles.profileGoalText, fontSize: 12, marginTop: 4 } }, canConfirm
            ? "Pick a goal, a diet, and a calorie target, preview it, then confirm to save it as your plan."
            : "Pick a goal, a diet, and a calorie target — we'll build today's meals from it on the spot. Nothing is saved; change any answer to regenerate."
          ),
      !locked && e("div", { style: { marginTop: 14 } },
        e("span", { style: { ...styles.profileLabel, display: "block", marginBottom: 6 } }, "Goal"),
        e(Segmented, { options: MEAL_GEN_GOAL_OPTIONS, value: genGoal, onChange: (v) => { setGenGoal(v); setGenCalories(null); } })
      ),
      !locked && e("div", { style: { marginTop: 12 } },
        e("span", { style: { ...styles.profileLabel, display: "block", marginBottom: 6 } }, "Diet"),
        e(Segmented, { options: MEAL_GEN_DIET_OPTIONS, value: genDiet, onChange: setGenDiet })
      ),
      !locked && e("div", { style: { marginTop: 12 } },
        e("span", { style: { ...styles.profileLabel, display: "block", marginBottom: 6 } }, "Calories"),
        e("div", { style: { display: "flex", gap: 8, flexWrap: "wrap" } },
          bands.map((kcal, i) => e("button", {
            key: i,
            style: {
              ...styles.demoLinkBtn,
              border: `1px solid ${genCalories === kcal ? C.brand : C.cardBorderStrong}`,
              ...(genCalories === kcal ? { color: C.brand, background: C.brandSoft } : {})
            },
            onClick: () => setGenCalories(kcal)
          }, `${bandLabels[i]} · ${kcal} kcal`))
        )
      ),
      result && e("div", { style: { marginTop: 18, paddingTop: 14, borderTop: `1px solid ${C.cardBorder}` } },
        e("div", { style: styles.dashGrid },
          e("div", { style: styles.trainerStatCard }, e("span", { style: styles.profileLabel }, "Calories"), e("span", { style: { ...styles.profileValue, display: "block" } }, `${result.achievedCalories} kcal`)),
          e("div", { style: styles.trainerStatCard }, e("span", { style: styles.profileLabel }, "Protein"), e("span", { style: { ...styles.profileValue, display: "block" } }, `${result.achievedProtein} g`)),
          e("div", { style: styles.trainerStatCard }, e("span", { style: styles.profileLabel }, "Carbs"), e("span", { style: { ...styles.profileValue, display: "block" } }, `${result.achievedCarbs} g`)),
          e("div", { style: styles.trainerStatCard }, e("span", { style: styles.profileLabel }, "Fat"), e("span", { style: { ...styles.profileValue, display: "block" } }, `${result.achievedFat} g`))
        ),
        result.showClosestMatchNote && e("div", { style: { ...styles.setupNotice, marginTop: 12 } },
          e(Icon, { name: "alert", size: 14, color: C.ink3 }),
          `Closest balanced match for this combination — about ${Math.abs(result.offBy)} kcal ${result.offBy > 0 ? "over" : "under"} your ${result.targetCalories} kcal target. This happens on the hardest macro combinations (e.g. high protein on plant foods) — still nutritionally balanced.`
        ),
        MEAL_GEN_MEAL_ORDER.filter((m) => result.meals[m].length > 0).map((m) => e("div", { key: m, style: { marginTop: 16 } },
          e(MealGroupHeader, { label: MEAL_GEN_MEAL_LABELS[m] }),
          e("div", { style: { display: "flex", flexDirection: "column", gap: 8, marginTop: 8 } },
            result.meals[m].map((it, i) => e(MealGenFoodRow, { key: `${it.food}-${i}`, food: it.food, grams: it.grams, accentColor: mealTheme(MEAL_GEN_MEAL_LABELS[m]).color }))
          )
        )),
        e("div", { style: { marginTop: 16 } },
          e("button", {
            style: { ...styles.energyPillBtn, display: "inline-flex", alignItems: "center", gap: 6 },
            onClick: () => setShowSwaps((v) => !v)
          }, e(Icon, { name: "swap", size: 13, color: C.brand }), showSwaps ? "Hide food swaps" : "Show food swaps"),
          showSwaps && e("div", { style: { marginTop: 8, display: "flex", flexDirection: "column", gap: 8 } },
            swaps.map((s, i) => e("div", { key: i },
              e("span", { style: { ...styles.goalChip, color: C.brand, background: C.brandSoft } }, s.group),
              e("p", { style: { ...styles.profileGoalText, fontSize: 12, marginTop: 4 } }, s.text)
            ))
          )
        ),
        e("p", { style: { ...styles.profileGoalText, fontSize: 11, marginTop: 16, color: C.ink3 } }, "General nutrition guidance for healthy adults — not medical or individualised advice. Doesn't account for allergies, intolerances, medical conditions, pregnancy, or medication. If you have a health condition or specific dietary need, work with your doctor or a registered dietitian. Adjust portions for your own tolerance, preferences, and hunger."),
        !locked && canConfirm && e("div", { style: { marginTop: 16 } },
          saveError && e("span", { style: { ...styles.inlineError, display: "block", marginBottom: 8 } }, saveError),
          e("button", { style: { ...styles.saveBtn, marginTop: 0, ...(saving ? styles.btnDisabled : {}) }, disabled: saving, onClick: handleConfirm },
            saving ? "Saving…" : "Confirm & save this plan →"
          ),
          e("p", { style: { ...styles.profileGoalText, fontSize: 11, marginTop: 6 } }, "Once confirmed, this becomes your plan — you won't be asked to choose again.")
        )
      )
    );
  }

  // Shared library of ready-made diet plans, tagged by goal (Fat loss / Muscle
  // gain / Maintenance / Recomp) — same relationship to a client's own diet
  // plan as ProgramsPanel has to ClientProgramCard: this is the catalog every
  // trainer builds from, a client's own pick just points at one entry here.
  // Meal items reuse MealItemForm/MealItemRow (they're plain presentational
  // components with no table baked in) against diet_template_meal_items
  // instead of diet_meal_items.
  function DietPlanTemplatesPanel({ canManage = false }) {
    const [goal, setGoal] = useState(DIET_GOALS[0].value);
    const [templates, setTemplates] = useState([]);
    const [itemsByTemplate, setItemsByTemplate] = useState({});
    const [loaded, setLoaded] = useState(false);
    const [error, setError] = useState("");

    const [newTemplateOpen, setNewTemplateOpen] = useState(false);
    const [templateForm, setTemplateForm] = useState(BLANK_DIET_TEMPLATE_FORM);
    const [savingTemplate, setSavingTemplate] = useState(false);
    const [editingTemplateId, setEditingTemplateId] = useState(null);
    // Sept 13 2026, Jimmy: inline "are you sure" instead of window.confirm()
    // — which ready plan (if any) has its delete button swapped for the
    // inline confirm bar.
    const [confirmDeleteTemplateId, setConfirmDeleteTemplateId] = useState(null);

    const [addMealTarget, setAddMealTarget] = useState(null); // { templateId, mealLabel }
    const [newMealFor, setNewMealFor] = useState(null); // templateId
    const [editItemTarget, setEditItemTarget] = useState(null); // { templateId, id }
    const [itemForm, setItemForm] = useState(BLANK_MEAL_ITEM_FORM);
    const [savingItem, setSavingItem] = useState(false);
    // Sept 12 2026, Jimmy: same "just the name + an arrow" collapse as the
    // Programs browse cards — a ready plan used to dump its description,
    // macros and full meal-by-meal breakdown for every plan under this goal
    // at once.
    const [expandedTemplateIds, setExpandedTemplateIds] = useState(() => new Set());
    function toggleTemplateExpanded(id) {
      setExpandedTemplateIds((prev) => {
        const next = new Set(prev);
        if (next.has(id)) next.delete(id); else next.add(id);
        return next;
      });
    }

    useEffect(() => {
      if (!sb) { setLoaded(true); return; }
      setLoaded(false);
      loadTemplates();
    }, [goal]);

    async function loadTemplates() {
      const { data: tpls, error: tplErr } = await sb.from("diet_plan_templates").select("*").eq("goal", goal).order("order_index", { ascending: true });
      if (tplErr || !tpls) { setTemplates([]); setItemsByTemplate({}); setLoaded(true); return; }
      setTemplates(tpls);
      if (tpls.length === 0) { setItemsByTemplate({}); setLoaded(true); return; }
      const ids = tpls.map((t) => t.id);
      const { data: itemRows } = await sb.from("diet_template_meal_items").select("*").in("template_id", ids).order("order_index", { ascending: true });
      const grouped = {};
      (itemRows || []).forEach((r) => { (grouped[r.template_id] = grouped[r.template_id] || []).push(r); });
      setItemsByTemplate(grouped);
      setLoaded(true);
    }

    function mealGroupsFor(templateId) {
      const rows = itemsByTemplate[templateId] || [];
      const byMeal = {};
      const order = [];
      rows.forEach((r) => {
        if (!byMeal[r.meal_label]) { byMeal[r.meal_label] = []; order.push(r.meal_label); }
        byMeal[r.meal_label].push(r);
      });
      return order.map((label) => ({ label, rows: byMeal[label] }));
    }

    function closeItemForm() {
      setAddMealTarget(null); setNewMealFor(null); setEditItemTarget(null);
      setItemForm(BLANK_MEAL_ITEM_FORM); setError("");
    }

    function openAddToMeal(templateId, mealLabel) {
      closeItemForm();
      setAddMealTarget({ templateId, mealLabel });
      setItemForm({ ...BLANK_MEAL_ITEM_FORM, mealLabel });
    }

    function openAddNewMeal(templateId) {
      closeItemForm();
      setNewMealFor(templateId);
      setItemForm(BLANK_MEAL_ITEM_FORM);
    }

    function openEditItem(templateId, item) {
      closeItemForm();
      setEditItemTarget({ templateId, id: item.id });
      setItemForm({
        mealLabel: item.meal_label, foodItem: item.food_item, portion: item.portion || "",
        calories: item.calories != null ? String(item.calories) : "",
        protein: item.protein != null ? String(item.protein) : "",
        carbs: item.carbs != null ? String(item.carbs) : "",
        fat: item.fat != null ? String(item.fat) : "",
        notes: item.notes || ""
      });
    }

    async function handleDeleteItem(templateId, id) {
      const removed = (itemsByTemplate[templateId] || []).find((r) => r.id === id) || null;
      setItemsByTemplate((prev) => ({ ...prev, [templateId]: (prev[templateId] || []).filter((r) => r.id !== id) }));
      if (!sb) return;
      const { error: err } = await sb.from("diet_template_meal_items").delete().eq("id", id);
      // Sept 19 2026 inspection fix: a failed delete used to leave the item
      // gone from the screen with no sign it's still in the database, then
      // it would just reappear next time loadTemplates() ran — put it back
      // and say so instead, same pattern as every other delete in the app.
      if (err && removed) {
        setItemsByTemplate((prev) => ({ ...prev, [templateId]: [...(prev[templateId] || []), removed].sort((a, b) => (a.order_index || 0) - (b.order_index || 0)) }));
        setError("Couldn't delete that food item — try again.");
      }
    }

    async function handleSaveItem() {
      if (!itemForm.foodItem.trim()) { setError("Enter a food item."); return; }
      if (newMealFor && !itemForm.mealLabel.trim()) { setError("Enter a meal name (e.g. Breakfast)."); return; }
      const macroErr = macroFieldError(itemForm);
      if (macroErr) { setError(macroErr); return; }
      if (!sb) { setError("Backend not configured yet."); return; }
      setError("");
      setSavingItem(true);

      if (editItemTarget) {
        const payload = {
          meal_label: itemForm.mealLabel.trim(),
          food_item: itemForm.foodItem.trim(),
          portion: itemForm.portion.trim() || null,
          calories: itemForm.calories === "" ? null : Number(itemForm.calories),
          protein: itemForm.protein === "" ? null : Number(itemForm.protein),
          carbs: itemForm.carbs === "" ? null : Number(itemForm.carbs),
          fat: itemForm.fat === "" ? null : Number(itemForm.fat),
          notes: itemForm.notes.trim() || null
        };
        const { data, error: err } = await sb.from("diet_template_meal_items").update(payload).eq("id", editItemTarget.id).select();
        setSavingItem(false);
        if (err || !data) { setError("Couldn't save those changes. Try again."); return; }
        setItemsByTemplate((prev) => ({
          ...prev,
          [editItemTarget.templateId]: (prev[editItemTarget.templateId] || []).map((r) => (r.id === editItemTarget.id ? data[0] : r))
        }));
        closeItemForm();
        return;
      }

      const templateId = addMealTarget ? addMealTarget.templateId : newMealFor;
      const mealLabel = addMealTarget ? addMealTarget.mealLabel : itemForm.mealLabel.trim();
      const existing = itemsByTemplate[templateId] || [];
      const payload = {
        template_id: templateId,
        meal_label: mealLabel,
        food_item: itemForm.foodItem.trim(),
        portion: itemForm.portion.trim() || null,
        calories: itemForm.calories === "" ? null : Number(itemForm.calories),
        protein: itemForm.protein === "" ? null : Number(itemForm.protein),
        carbs: itemForm.carbs === "" ? null : Number(itemForm.carbs),
        fat: itemForm.fat === "" ? null : Number(itemForm.fat),
        notes: itemForm.notes.trim() || null,
        order_index: existing.length
      };
      const { data, error: err } = await sb.from("diet_template_meal_items").insert([payload]).select();
      setSavingItem(false);
      if (err || !data) { setError("Couldn't save that food item. Try again."); return; }
      setItemsByTemplate((prev) => ({ ...prev, [templateId]: [...(prev[templateId] || []), data[0]] }));
      closeItemForm();
    }

    async function handleCreateTemplate() {
      if (!templateForm.name.trim()) { setError("Enter a plan name."); return; }
      const macroErr = dietTemplateFieldError(templateForm);
      if (macroErr) { setError(macroErr); return; }
      if (!sb) { setError("Backend not configured yet."); return; }
      setError("");
      setSavingTemplate(true);
      const payload = {
        goal, name: templateForm.name.trim(), description: templateForm.description.trim() || null,
        calories_target: templateForm.calories === "" ? null : Number(templateForm.calories),
        protein_target: templateForm.protein === "" ? null : Number(templateForm.protein),
        carbs_target: templateForm.carbs === "" ? null : Number(templateForm.carbs),
        fat_target: templateForm.fat === "" ? null : Number(templateForm.fat),
        water_target_ml: templateForm.water === "" ? null : Number(templateForm.water),
        // Sept 19 2026 inspection fix: templates.length collides with an
        // existing order_index as soon as any template in this goal has
        // ever been deleted (e.g. 2 templates at index 0/1, #0 deleted,
        // length is now 1 — the same index the surviving template already
        // has). Deriving from the actual max index in use is stable
        // regardless of past deletes.
        order_index: templates.length > 0 ? Math.max(...templates.map((t) => t.order_index || 0)) + 1 : 0
      };
      const { data, error: err } = await sb.from("diet_plan_templates").insert([payload]).select();
      setSavingTemplate(false);
      if (err || !data) { setError("Couldn't create that plan. Try again."); return; }
      setTemplates((prev) => [...prev, data[0]]);
      setItemsByTemplate((prev) => ({ ...prev, [data[0].id]: [] }));
      setExpandedTemplateIds((prev) => new Set(prev).add(data[0].id));
      setTemplateForm(BLANK_DIET_TEMPLATE_FORM);
      setNewTemplateOpen(false);
    }

    function openEditTemplate(t) {
      setEditingTemplateId(t.id);
      setTemplateForm({
        name: t.name, description: t.description || "",
        calories: t.calories_target != null ? String(t.calories_target) : "",
        protein: t.protein_target != null ? String(t.protein_target) : "",
        carbs: t.carbs_target != null ? String(t.carbs_target) : "",
        fat: t.fat_target != null ? String(t.fat_target) : "",
        water: t.water_target_ml != null ? String(t.water_target_ml) : ""
      });
      setNewTemplateOpen(false);
      setError("");
      // Keep the card open after Save, same reasoning as ProgramsPanel's
      // openEditProgram.
      setExpandedTemplateIds((prev) => new Set(prev).add(t.id));
    }

    async function handleSaveTemplate() {
      if (!templateForm.name.trim()) { setError("Enter a plan name."); return; }
      const macroErr = dietTemplateFieldError(templateForm);
      if (macroErr) { setError(macroErr); return; }
      if (!sb) { setError("Backend not configured yet."); return; }
      setError("");
      setSavingTemplate(true);
      const payload = {
        name: templateForm.name.trim(), description: templateForm.description.trim() || null,
        calories_target: templateForm.calories === "" ? null : Number(templateForm.calories),
        protein_target: templateForm.protein === "" ? null : Number(templateForm.protein),
        carbs_target: templateForm.carbs === "" ? null : Number(templateForm.carbs),
        fat_target: templateForm.fat === "" ? null : Number(templateForm.fat),
        water_target_ml: templateForm.water === "" ? null : Number(templateForm.water)
      };
      const { data, error: err } = await sb.from("diet_plan_templates").update(payload).eq("id", editingTemplateId).select();
      setSavingTemplate(false);
      if (err || !data) { setError("Couldn't save those changes. Try again."); return; }
      setTemplates((prev) => prev.map((t) => (t.id === editingTemplateId ? data[0] : t)));
      setEditingTemplateId(null);
      setTemplateForm(BLANK_DIET_TEMPLATE_FORM);
    }

    // Sept 19 2026 inspection fix: deleting a ready plan a client is
    // actively on used to silently blank their visible diet plan — no
    // warning here mentioned active clients, even though the app already
    // has a "retire instead" convention (a "[DO NOT USE] " name prefix
    // hides a plan from every client-facing browse/pick/reactivate list —
    // see isRetiredTemplate — while leaving it, and anyone already on it,
    // completely intact). openDeleteConfirm checks how many real diet_plans
    // rows still point at this template before the confirm bar renders, so
    // that choice is informed instead of a blind delete.
    const [deleteImpactCount, setDeleteImpactCount] = useState(null);
    async function openDeleteConfirm(templateId) {
      setConfirmDeleteTemplateId(templateId);
      setDeleteImpactCount(null);
      if (!sb) return;
      const { count } = await sb.from("diet_plans").select("id", { count: "exact", head: true }).eq("template_id", templateId);
      setDeleteImpactCount(count || 0);
    }
    async function handleRetireTemplate(t) {
      if (!sb) return;
      setConfirmDeleteTemplateId(null);
      const { data, error: err } = await sb.from("diet_plan_templates").update({ name: `[DO NOT USE] ${t.name}` }).eq("id", t.id).select();
      if (!err && data) { setTemplates((prev) => prev.map((x) => (x.id === t.id ? data[0] : x))); return; }
      setError("Couldn't retire that plan — try again.");
    }
    async function handleDeleteTemplate(id) {
      setConfirmDeleteTemplateId(null);
      const removedTemplate = templates.find((t) => t.id === id) || null;
      const removedItems = itemsByTemplate[id] || null;
      setTemplates((prev) => prev.filter((t) => t.id !== id));
      setItemsByTemplate((prev) => { const next = { ...prev }; delete next[id]; return next; });
      if (!sb) return;
      const { error: err } = await sb.from("diet_plan_templates").delete().eq("id", id);
      // Sept 19 2026 inspection fix: a failed delete used to leave the plan
      // gone from the screen with no sign it's still in the database, then
      // it would just reappear next time loadTemplates() ran — put it back
      // and say so instead, same pattern as every other delete in the app.
      if (err && removedTemplate) {
        setTemplates((prev) => [...prev, removedTemplate].sort((a, b) => (a.order_index || 0) - (b.order_index || 0)));
        if (removedItems) setItemsByTemplate((prev) => ({ ...prev, [id]: removedItems }));
        setError("Couldn't delete that plan — try again.");
      }
    }

    if (!loaded) return e("div", { style: styles.empty }, e("p", { style: styles.emptyText }, "Loading diet plans…"));

    return e("div", null,
      e("div", { style: styles.sectionHead }, e("span", { style: styles.sectionTitle }, "Ready diet plans")),
      e("p", { style: { ...styles.profileGoalText, fontSize: 12, marginBottom: 14 } },
        "Build once here, then clients can browse and buy a ready plan by goal instead of waiting on a custom one."
      ),
      e(Segmented, { options: DIET_GOALS, value: goal, onChange: setGoal }),
      error && e("div", { style: { ...styles.errorBanner, margin: "12px 0 0" } }, e(Icon, { name: "x", size: 13, color: C.critical }), error),
      canManage && e("div", { style: { marginTop: 14 } },
        newTemplateOpen
          ? e("div", { style: { ...styles.sessionForm, marginTop: 0, marginBottom: 0 } },
              e("input", { style: styles.input, placeholder: "Plan name (e.g. Lean Cut — 1800 kcal)", value: templateForm.name, onChange: (ev) => setTemplateForm({ ...templateForm, name: ev.target.value }) }),
              e("input", { style: { ...styles.input, marginTop: 8 }, placeholder: "Description (optional)", value: templateForm.description, onChange: (ev) => setTemplateForm({ ...templateForm, description: ev.target.value }) }),
              e("div", { style: { display: "flex", gap: 8, marginTop: 8 } },
                e("input", { style: { ...styles.input, flex: 1 }, type: "number", placeholder: "Calories", value: templateForm.calories, onChange: (ev) => setTemplateForm({ ...templateForm, calories: ev.target.value }) }),
                e("input", { style: { ...styles.input, flex: 1 }, type: "number", placeholder: "Protein (g)", value: templateForm.protein, onChange: (ev) => setTemplateForm({ ...templateForm, protein: ev.target.value }) })
              ),
              e("div", { style: { display: "flex", gap: 8, marginTop: 8 } },
                e("input", { style: { ...styles.input, flex: 1 }, type: "number", placeholder: "Carbs (g)", value: templateForm.carbs, onChange: (ev) => setTemplateForm({ ...templateForm, carbs: ev.target.value }) }),
                e("input", { style: { ...styles.input, flex: 1 }, type: "number", placeholder: "Fat (g)", value: templateForm.fat, onChange: (ev) => setTemplateForm({ ...templateForm, fat: ev.target.value }) })
              ),
              e("input", { style: { ...styles.input, marginTop: 8 }, type: "number", placeholder: "Water (ml, optional)", value: templateForm.water, onChange: (ev) => setTemplateForm({ ...templateForm, water: ev.target.value }) }),
              e("div", { style: { display: "flex", gap: 8, marginTop: 10 } },
                e("button", { style: { ...styles.saveBtn, marginTop: 0, flex: 1, ...(savingTemplate ? styles.btnDisabled : {}) }, disabled: savingTemplate, onClick: handleCreateTemplate }, savingTemplate ? "Creating…" : "Create plan"),
                e("button", { style: { ...styles.demoLinkBtn, padding: "0 10px" }, onClick: () => { setNewTemplateOpen(false); setTemplateForm(BLANK_DIET_TEMPLATE_FORM); setError(""); } }, "Cancel")
              )
            )
          : e("button", { style: styles.newBtn, onClick: () => { setNewTemplateOpen(true); setEditingTemplateId(null); setTemplateForm(BLANK_DIET_TEMPLATE_FORM); setError(""); } }, e(Icon, { name: "plus", size: 15, strokeWidth: 3 }), "New ready plan")
      ),
      templates.length === 0 && e("div", { style: styles.empty }, e(ProgramsEmptyArt, {}), e("p", { style: styles.emptyText }, canManage ? "No ready plans yet for this goal — create one above." : "No ready plans yet for this goal.")),
      templates.map((t) => {
        const expanded = expandedTemplateIds.has(t.id) || editingTemplateId === t.id;
        return e("div", { key: t.id, style: styles.programCard },
        editingTemplateId === t.id
          ? e("div", { style: { ...styles.sessionForm, marginTop: 0, marginBottom: 0 } },
              e("input", { style: styles.input, placeholder: "Plan name", value: templateForm.name, onChange: (ev) => setTemplateForm({ ...templateForm, name: ev.target.value }) }),
              e("input", { style: { ...styles.input, marginTop: 8 }, placeholder: "Description (optional)", value: templateForm.description, onChange: (ev) => setTemplateForm({ ...templateForm, description: ev.target.value }) }),
              e("div", { style: { display: "flex", gap: 8, marginTop: 8 } },
                e("input", { style: { ...styles.input, flex: 1 }, type: "number", placeholder: "Calories", value: templateForm.calories, onChange: (ev) => setTemplateForm({ ...templateForm, calories: ev.target.value }) }),
                e("input", { style: { ...styles.input, flex: 1 }, type: "number", placeholder: "Protein (g)", value: templateForm.protein, onChange: (ev) => setTemplateForm({ ...templateForm, protein: ev.target.value }) })
              ),
              e("div", { style: { display: "flex", gap: 8, marginTop: 8 } },
                e("input", { style: { ...styles.input, flex: 1 }, type: "number", placeholder: "Carbs (g)", value: templateForm.carbs, onChange: (ev) => setTemplateForm({ ...templateForm, carbs: ev.target.value }) }),
                e("input", { style: { ...styles.input, flex: 1 }, type: "number", placeholder: "Fat (g)", value: templateForm.fat, onChange: (ev) => setTemplateForm({ ...templateForm, fat: ev.target.value }) })
              ),
              e("input", { style: { ...styles.input, marginTop: 8 }, type: "number", placeholder: "Water (ml, optional)", value: templateForm.water, onChange: (ev) => setTemplateForm({ ...templateForm, water: ev.target.value }) }),
              e("div", { style: { display: "flex", gap: 8, marginTop: 10 } },
                e("button", { style: { ...styles.saveBtn, marginTop: 0, flex: 1, ...(savingTemplate ? styles.btnDisabled : {}) }, disabled: savingTemplate, onClick: handleSaveTemplate }, savingTemplate ? "Saving…" : "Save"),
                e("button", { style: { ...styles.demoLinkBtn, padding: "0 10px" }, onClick: () => { setEditingTemplateId(null); setTemplateForm(BLANK_DIET_TEMPLATE_FORM); setError(""); } }, "Cancel")
              )
            )
          : e("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 8 } },
              e("div", { style: styles.programHeader },
                // Sept 12 2026, Jimmy: same collapse-to-just-the-name pattern
                // as the Programs browse cards — description, macros, and the
                // full meal-by-meal breakdown all now wait behind this arrow.
                e("div", { style: { display: "flex", alignItems: "center", gap: 8 } },
                  e("span", { style: { ...styles.sectionTitle, minWidth: 0, wordBreak: "break-word" } }, t.name),
                  e("button", {
                    style: { ...styles.expandToggleBtn, ...(expanded ? styles.expandToggleBtnOpen : {}) },
                    onClick: () => toggleTemplateExpanded(t.id),
                    "aria-label": expanded ? `Hide details for ${t.name}` : `Show details for ${t.name}`,
                    title: expanded ? "Hide details" : "Show details"
                  }, e(Icon, { name: "chevron", size: 14, strokeWidth: 2.6 }))
                ),
                expanded && t.description && e("p", { style: { ...styles.profileGoalText, marginTop: 8 } }, t.description),
                expanded && e("p", { style: { ...styles.profileGoalText, marginTop: 4, fontSize: 12 } },
                  [t.calories_target != null && `${t.calories_target} kcal`, t.protein_target != null && `${t.protein_target}g protein`, t.carbs_target != null && `${t.carbs_target}g carbs`, t.fat_target != null && `${t.fat_target}g fat`, t.water_target_ml != null && `${t.water_target_ml}ml water`].filter(Boolean).join(" · ") || "No macros set"
                )
              ),
              canManage && e("div", { style: { display: "flex", gap: 2, flexShrink: 0 } },
                e("button", { style: styles.editBtn, onClick: () => openEditTemplate(t), "aria-label": "Edit plan" }, e(Icon, { name: "edit", size: 14 })),
                e("button", { style: styles.deleteBtn, onClick: () => openDeleteConfirm(t.id), "aria-label": "Delete plan" }, e(Icon, { name: "trash", size: 15 }))
              )
            ),
        confirmDeleteTemplateId === t.id && e("div", { style: { ...styles.deleteConfirmBar, flexDirection: "column", alignItems: "stretch", gap: 8, marginTop: 10 } },
          e("span", { style: styles.deleteConfirmText },
            deleteImpactCount == null
              ? "Checking whether any clients are on this plan…"
              : deleteImpactCount > 0
              ? `${deleteImpactCount} client${deleteImpactCount === 1 ? " is" : "s are"} actively on this plan — deleting it blanks their diet plan back to "no plan assigned" with no warning to them. Retire it instead to hide it from new picks without touching anyone already on it, or delete anyway.`
              : "Delete this whole ready diet plan, including every meal and food item in it? No clients are currently on it."
          ),
          e("div", { style: { display: "flex", gap: 6, flexWrap: "wrap" } },
            e("button", { type: "button", style: styles.setConfirmCancelBtn, onClick: () => setConfirmDeleteTemplateId(null) }, "Cancel"),
            deleteImpactCount > 0 && e("button", { type: "button", style: styles.demoLinkBtn, onClick: () => handleRetireTemplate(t) }, "Retire instead"),
            e("button", { type: "button", style: styles.setConfirmDangerBtn, disabled: deleteImpactCount == null, onClick: () => handleDeleteTemplate(t.id) }, "Delete anyway")
          )
        ),
        expanded && mealGroupsFor(t.id).map((meal) => e("div", { key: meal.label, style: { marginTop: 16 } },
          e(MealGroupHeader, { label: meal.label }),
          e("div", { style: { display: "flex", flexDirection: "column", gap: 8, marginTop: 8 } },
            meal.rows.map((item) => (
              editItemTarget && editItemTarget.id === item.id
                ? e(MealItemForm, { key: item.id, values: itemForm, onChange: setItemForm, onSave: handleSaveItem, onCancel: closeItemForm, saving: savingItem, showMealField: true, saveLabel: "Save changes" })
                : e(MealItemRow, { key: item.id, item, canManage, onEdit: (row) => openEditItem(t.id, row), onDelete: (id) => handleDeleteItem(t.id, id), accentColor: mealTheme(meal.label).color })
            ))
          ),
          canManage && (
            addMealTarget && addMealTarget.templateId === t.id && addMealTarget.mealLabel === meal.label
              ? e(MealItemForm, { values: itemForm, onChange: setItemForm, onSave: handleSaveItem, onCancel: closeItemForm, saving: savingItem, showMealField: false })
              : e("button", { style: styles.demoLinkBtn, onClick: () => openAddToMeal(t.id, meal.label) }, "+ Add food item")
          )
        )),
        expanded && canManage && e("div", { style: { marginTop: 16 } },
          newMealFor === t.id
            ? e(MealItemForm, { values: itemForm, onChange: setItemForm, onSave: handleSaveItem, onCancel: closeItemForm, saving: savingItem, showMealField: true, saveLabel: "Add meal" })
            : e("button", { style: styles.demoLinkBtn, onClick: () => openAddNewMeal(t.id) }, "+ Add a new meal")
        )
      );
      })
    );
  }

